CREATE OR REPLACE FUNCTION migration.round_amount(p_amount numeric, p_digits integer)
RETURNS TABLE(rounded numeric)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
  factor numeric;
  tmp numeric;
BEGIN
  -- NULL propagation like SQL Server
  IF p_amount IS NULL THEN
    RETURN QUERY SELECT NULL::numeric;
    RETURN;
  END IF;

  IF p_digits >= 0 THEN
    factor := power(10::numeric, p_digits);
    IF p_amount >= 0 THEN
      tmp := floor(p_amount * factor + 0.5) / factor; -- half away from zero for positives
    ELSE
      tmp := ceil(p_amount * factor - 0.5) / factor;  -- half away from zero for negatives
    END IF;
  ELSE
    -- negative digits: round to left of decimal point
    factor := power(10::numeric, -p_digits);
    IF p_amount >= 0 THEN
      tmp := floor(p_amount / factor + 0.5) * factor;
    ELSE
      tmp := ceil(p_amount / factor - 0.5) * factor;
    END IF;
  END IF;

  -- match SQL Server CAST(... AS decimal(19,4)) by returning numeric with scale 4
  RETURN QUERY SELECT tmp::numeric(19,4) AS rounded;
END;
$$;

