CREATE OR REPLACE FUNCTION migration.cursor_total(p_policy_id integer)
RETURNS TABLE(total numeric) 
LANGUAGE plpgsql
SECURITY INVOKER
AS $func$
DECLARE
    r RECORD;
    v_amount numeric(19,4);
    v_total numeric(19,2) := 0;
    -- helper to emulate SQL Server ROUND(...,2) which rounds halves away from zero
    FUNCTION round_sqlserver(val numeric)
    RETURNS numeric
    LANGUAGE plpgsql
    AS $f$
    DECLARE
        sgn integer;
        av numeric;
    BEGIN
        IF val IS NULL THEN
            RETURN NULL;
        END IF;
        sgn := CASE WHEN val < 0 THEN -1 ELSE 1 END;
        av := abs(val);
        -- multiply, add 0.5 and floor to achieve half-away-from-zero behavior, then divide
        RETURN (sgn * floor(av * 100 + 0.5) / 100)::numeric(19,2);
    END;
    $f$;
BEGIN
    FOR r IN SELECT amount FROM domain.premiums WHERE policy_id = p_policy_id ORDER BY id LOOP
        v_amount := r.amount;
        v_total := v_total + COALESCE(round_sqlserver(v_amount), 0);
    END LOOP;

    RETURN QUERY SELECT v_total::numeric;
END;
$func$;

