    -- este procedure se ejecuta como una unidad atómica desde el cliente/autocommit).
    UPDATE domain.policies
    SET status = 'CANCELLED'
    WHERE id = p_policy_id;

    INSERT INTO domain.movements(id, policy_id, kind, amount)
    SELECT COALESCE(MAX(id), 0) + 1, p_policy_id, 'CANCEL', 0::numeric
    FROM domain.movements;

    result := 'CANCELLED';
EXCEPTION WHEN OTHERS THEN
    -- Re-lanzar la excepción para que el cliente/llamador vea el error y la transacción
    -- sea revertida por el motor; no se aíslan códigos numéricos tal como en THROW.
    RAISE;
END;
$$;

